// Serve a foto de capa do presente como imagem de verdade (não como
// data URL), pra poder ser usada em og:image nas prévias de link do
// WhatsApp/Instagram. Se o presente não tiver foto (ou não existir),
// cai no mascote padrão do site.
import { getStore } from '@netlify/blobs';

const MASCOTE_FALLBACK = "data:image/png;base64,";

function decodificar(dataUrl) {
  const m = /^data:([^;]+);base64,(.+)$/.exec(dataUrl || '');
  if (!m) return null;
  return { tipo: m[1], buffer: Buffer.from(m[2], 'base64') };
}

export default async (req) => {
  try {
    const url = new URL(req.url);
    const id = url.searchParams.get('id') || '';
    let dataUrl = null;
    if (id) {
      try {
        const g = await getStore('presentes').get(id, { type: 'json' });
        const foto = g && Array.isArray(g.fotos) && g.fotos.filter(Boolean)[0];
        if (foto && foto.src) dataUrl = foto.src;
      } catch {}
    }
    const decodificado = decodificar(dataUrl) || decodificar(MASCOTE_FALLBACK);
    if (!decodificado) return new Response('', { status: 404 });
    return new Response(decodificado.buffer, {
      status: 200,
      headers: { 'Content-Type': decodificado.tipo, 'Cache-Control': 'public, max-age=3600' }
    });
  } catch (e) {
    console.error('foto-og:', e && e.stack || e);
    return new Response('', { status: 500 });
  }
};
